import{_ as r,o as a,c as t,al as o}from"./chunks/framework.7vp1BMOE.js";const c=JSON.parse('{"title":"Керівництво з перенесення контролера польоту","description":"","frontmatter":{},"headers":[],"relativePath":"uk/hardware/porting_guide.md","filePath":"uk/hardware/porting_guide.md"}'),i={name:"uk/hardware/porting_guide.md"};function l(n,e,s,d,h,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="керівництво-з-перенесення-контролера-польоту" tabindex="-1">Керівництво з перенесення контролера польоту <a class="header-anchor" href="#керівництво-з-перенесення-контролера-польоту" aria-label="Permalink to &quot;Керівництво з перенесення контролера польоту&quot;">​</a></h1><p>This topic is for developers who want to port PX4 to work with <em>new</em> flight controller hardware.</p><h2 id="архітектура-системи-px4" tabindex="-1">Архітектура системи PX4 <a class="header-anchor" href="#архітектура-системи-px4" aria-label="Permalink to &quot;Архітектура системи PX4&quot;">​</a></h2><p>PX4 consists of two main layers: The <a href="./../middleware/">board support and middleware layer</a> on top of the host OS (NuttX, Linux or any other POSIX platform like Mac OS), and the applications (Flight Stack in <a href="https://github.com/PX4/PX4-Autopilot/tree/main/src/modules" target="_blank" rel="noreferrer">src/modules</a>). Please reference the <a href="./../concept/architecture">PX4 Architectural Overview</a> for more information.</p><p>Цей посібник спрямований лише на операційну систему хоста та проміжне програмне забезпечення, оскільки програми/стек польоту будуть працювати на будь-якій цільовій платі.</p><h2 id="налаштування-режиму-польоту-фаиловоі-структури" tabindex="-1">Налаштування режиму польоту файлової структури <a class="header-anchor" href="#налаштування-режиму-польоту-фаиловоі-структури" aria-label="Permalink to &quot;Налаштування режиму польоту файлової структури&quot;">​</a></h2><p>Board startup and configuration files are located under <a href="https://github.com/PX4/PX4-Autopilot/tree/main/boards/" target="_blank" rel="noreferrer">/boards</a> in each board&#39;s vendor-specific directory (i.e. <strong>boards/<em>VENDOR</em>/<em>MODEL</em>/</strong>).</p><p>Наприклад, для FMUv5:</p><ul><li>(All) Board-specific files: <a href="https://github.com/PX4/PX4-Autopilot/tree/main/boards/px4/fmu-v5" target="_blank" rel="noreferrer">/boards/px4/fmu-v5</a>.</li><li>Build configuration: <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v5/default.px4board" target="_blank" rel="noreferrer">/boards/px4/fmu-v5/default.px4board</a>.</li><li>Board-specific initialisation file: <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v5/init/rc.board_defaults" target="_blank" rel="noreferrer">/boards/px4/fmu-v5/init/rc.board_defaults</a><ul><li>A board-specific initialisation file is automatically included in startup scripts if found under the boards directory at <strong>init/rc.board</strong>.</li><li>Файл використовується для запуску сенсорів (та інших речей), які існують лише на конкретній платі. Це також може бути використано для встановлення параметрів за замовчуванням дошки, відображень UART та будь-яких інших виняткових випадків.</li><li>Для FMUv5 ви можете побачити, як запускаються всі датчики Pixhawk 4, а також встановлюється більший LOGGER_BUF.</li></ul></li></ul><h2 id="конфігурація-операціиноі-системи-хоста" tabindex="-1">Конфігурація операційної системи хоста <a class="header-anchor" href="#конфігурація-операціиноі-системи-хоста" aria-label="Permalink to &quot;Конфігурація операційної системи хоста&quot;">​</a></h2><p>Цей розділ описує призначення та місцезнаходження файлів конфігурації, необхідних для кожної підтримуваної операційної системи хоста, щоб перенести їх на нове апаратне засіб керування польотом.</p><h3 id="nuttx" tabindex="-1">NuttX <a class="header-anchor" href="#nuttx" aria-label="Permalink to &quot;NuttX&quot;">​</a></h3><p>See <a href="./porting_guide_nuttx">NuttX Board Porting Guide</a>.</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>Плати Linux не включають ОС та конфігурацію ядра. Ці дані вже надаються зображенням Linux, доступним для плати (яке повинно підтримувати інерційні сенсори з коробки).</p><ul><li><a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/raspberrypi/default.px4board" target="_blank" rel="noreferrer">boards/px4/raspberrypi/default.px4board</a> - RPi cross-compilation. </li></ul><h2 id="компоненти-та-конфігурація-проміжного-програмного-забезпечення" tabindex="-1">Компоненти та конфігурація проміжного програмного забезпечення <a class="header-anchor" href="#компоненти-та-конфігурація-проміжного-програмного-забезпечення" aria-label="Permalink to &quot;Компоненти та конфігурація проміжного програмного забезпечення&quot;">​</a></h2><p>Цей розділ описує різноманітні компоненти проміжного програмного забезпечення та необхідні оновлення файлів конфігурації для перенесення їх на нове апаратне засіб керування польотом.</p><h3 id="qurt-шестикутник" tabindex="-1">QuRT / Шестикутник <a class="header-anchor" href="#qurt-шестикутник" aria-label="Permalink to &quot;QuRT / Шестикутник&quot;">​</a></h3><ul><li>The start script is located in <a href="https://github.com/PX4/PX4-Autopilot/tree/main/posix-configs" target="_blank" rel="noreferrer">posix-configs/</a>. </li><li>Конфігурація ОС є частиною стандартного образу Linux (TODO: Вказати місце розташування ОБРАЗУ LINUX та інструкції щодо прошивки).</li><li>The PX4 middleware configuration is located in <a href="https://github.com/PX4/PX4-Autopilot/tree/main/boards" target="_blank" rel="noreferrer">src/boards</a>. TODO: ADD BUS CONFIG</li></ul><h2 id="рекомендаціі-з-підключення-rc-uart" tabindex="-1">Рекомендації з підключення RC UART <a class="header-anchor" href="#рекомендаціі-з-підключення-rc-uart" aria-label="Permalink to &quot;Рекомендації з підключення RC UART&quot;">​</a></h2><p>Зазвичай рекомендується підключати RC через окремі піни RX та TX до мікроконтролера. Якщо, проте, RX та TX з&#39;єднані разом, UART повинен бути переведений в режим одножильного кабелю, щоб уникнути будь-яких конфліктів. Це робиться за допомогою конфігураційної дошки та файлів маніфесту. One example is <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v5/src/manifest.c" target="_blank" rel="noreferrer">px4fmu-v5</a>. </p><h2 id="getting-your-board-supported" tabindex="-1">Getting Your Board Supported <a class="header-anchor" href="#getting-your-board-supported" aria-label="Permalink to &quot;Getting Your Board Supported&quot;">​</a></h2><p>This page covers the <em>technical</em> work of porting PX4 to new hardware. The <em>process</em> for getting that port reviewed, merged, and listed on the PX4 website, including board IDs, USB VID/PID, flight-test evidence, and maintenance expectations, is documented separately:</p><ul><li><a href="./../hardware/board_support_guide">Manufacturer&#39;s PX4 Board Support Guide</a></li></ul><p>In short: build your own firmware target based on PX4, demonstrate stable flight on the current release, and open a pull request with your board support code, documentation, and flight logs. The board support guide explains each step.</p><p>The PX4 project supports and maintains the <a href="./../hardware/reference_design">FMU standard reference hardware</a> and any boards compatible with the standard, including the <a href="./../flight_controller/pixhawk_series">Pixhawk series</a> (see the <a href="./../flight_controller/">full list of supported hardware</a>). Boards merged into PX4 benefit from a port in the repository, firmware builds accessible from <em>QGroundControl</em>, compatibility with the rest of the ecosystem, and automated CI checks.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The cost of maintaining a port is proportional to how far it diverges from the standard. Consider that cost before deviating: staying close to the reference design lets you benefit from day-to-day PX4 development with minimal maintenance burden.</p></div><p>Manufacturers are responsible for keeping their port up to date and working across PX4 releases. The PX4 project reserves the right to refuse or remove ports that do not meet the project&#39;s requirements, and all contributors are expected to follow the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/CODE_OF_CONDUCT.md" target="_blank" rel="noreferrer">Code of Conduct</a>.</p><h2 id="пов-язана-інформація" tabindex="-1">Пов&#39;язана інформація <a class="header-anchor" href="#пов-язана-інформація" aria-label="Permalink to &quot;Пов&#39;язана інформація&quot;">​</a></h2><ul><li><a href="./../middleware/drivers">Device Drivers</a> - How to support new peripheral hardware (device drivers)</li><li><a href="./../dev_setup/building_px4">Building the Code</a> - How to build source and upload firmware</li><li>Підтримувані автопілоти включають: <ul><li><a href="./../flight_controller/">Autopilot Hardware</a></li><li><a href="https://github.com/PX4/PX4-Autopilot/#supported-hardware" target="_blank" rel="noreferrer">Supported boards list</a> (Github) - Boards for which PX4-Autopilot has specific code</li></ul></li><li><a href="./../peripherals/">Supported Peripherals</a></li></ul>',31)])])}const f=r(i,[["render",l]]);export{c as __pageData,f as default};
